  function select(ids:number[]){setSelectedEntries([]);if(picking&&ids.length){const target=level?.entities.find(e=>e.id===ids[0]),source=level?.entities.find(e=>e.id===picking.ids[0]),field=source?.nativeProperties?.find(p=>p.field.name===picking.field)?.field;if(picking.field==='__channel'){try{const ops=channelLinkOperations(level?.entities??[],picking.ids,ids[0]);if(ops.length)applyParameters(ops);setPicking(null);setError('');setStatus('已共享目标频道；目标频道中的其他机关也会参与联动');}catch(e){setError(String(e));}return;}if(picking.field==='turn_order_id'){if(target?.type==='Guy'){applyParameters([{kind:'control',id:picking.ids[0],ids:picking.ids,targetId:target.id}]);setPicking(null);}else setError('同步目标必须是本关角色');return;}if(target&&(!field?.targets||field.targets.includes(target.type))){append(picking.ids.map(id=>({kind:'properties',id,values:{[picking.field]:target.id}})));setPicking(null);setStatus('已关联目标');}else setError('该物件不是此关联的有效目标');return;}setSelection(ids);setEntryId(null);setDraft([]);}
  function quickLink(){if(!selected.length||selected.some(e=>!ordinaryChannelObject(e)||!canModify(e,display,layer))){setError('先选中可编辑的普通开关或普通门闸');return;}cancelPlacementOnly();setError('');setPicking({field:'__channel',ids:selected.map(e=>e.id)});setStatus('点选目标普通开关或门闸，所选物件将加入目标频道；Esc 取消');}
  function organizationSelection():ObjectKey[]{return[...selection.map(entityKey),...new Set([...selectedEntries,...entryId?[entryId]:[]])].map(k=>typeof k==='string'&&k.startsWith('entity:')?k:entryKey(String(k)))as ObjectKey[];}
  function organizationAllowed(key:ObjectKey){if(keyLocked(key,display)||!keyVisible(key,display))return false;if(key.startsWith('entry:'))return Boolean(world?.map.entries.some(e=>entryKey(e.id)===key));const e=level?.entities.find(e=>entityKey(e.id)===key);return Boolean(e&&e.cloneable&&canModify(e,display,layer)&&!protectedCameraIds.has(e.id)&&!['Wall_Set','Ocean_Map'].includes(e.type)&&(view!=='world'||(e.id>>>20)===900));}
  function toggleObjectStates(keys:ObjectKey[],kind:'hidden'|'locked',value:boolean){window.dispatchEvent(new Event('sstar:cancel-gesture'));const objects={...display.objects};for(const k of keys)objects[k]={...objects[k],[kind]:value};changeDisplay({...display,objects});}
  function setOrganization(meta:EditorMetadata){const w=clone(current.current!);if(view==='world')w.map.editor=meta;else w.levels.find(l=>l.id===view)!.project.editor=meta;update(w,true,current.current,true);}
  function selectOrganization(keys:ObjectKey[]){setSelection(keys.filter(k=>k.startsWith('entity:')).map(k=>Number(k.slice(7))));const entries=keys.filter(k=>k.startsWith('entry:')).map(k=>k.slice(6));setSelectedEntries(entries);setEntryId(entries[0]??null);setFit(n=>n+1);}
  function copyOrganization(keys:ObjectKey[]){if(keys.some(k=>!organizationAllowed(k))){setError('分组包含锁定或不能复制的物件');return;}const w=clone(current.current!),p=view==='world'?w.map:w.levels.find(l=>l.id===view)!.project;let id=nextId();const used=reservedIds();const copies=keys.filter(k=>k.startsWith('entity:')).map(k=>{while(used.has(id))id++;const newId=id++;used.add(newId);return{id:Number(k.slice(7)),newId};});const map=new Map<ObjectKey,ObjectKey>(copies.map(c=>[entityKey(c.id),entityKey(c.newId)]));if(copies.length){const op:EditOp={kind:'duplicate',id:copies[0].id,copies,offset:[1,0,0],associations:'independent'};if(view==='world'){w.map.objects??=[];w.map.objects.push(op);}else w.levels.find(l=>l.id===view)!.project.operations.push(op);}for(const k of keys.filter(k=>k.startsWith('entry:'))){const old=w.map.entries.find(e=>entryKey(e.id)===k)!;if(old.x+1>=w.map.width){setError('入口副本超出地图范围');return;}const next={...old,id:uid('entry'),x:old.x+1};w.map.entries.push(next);map.set(k,entryKey(next.id));}p.editor??={groups:[]};p.editor.groups.push(...copyGroups(p.editor,map,uid('copy')));update(w);selectOrganization([...map.values()]);}
  function openArray(){if(!selected.length||selected.some(e=>!canModify(e,display,layer)||!designObject(e)||['Wall_Set','Ocean_Map','Level_Entry'].includes(e.type)||protectedCameraIds.has(e.id))){setError('先选择可复制的玩法物件');return;}window.dispatchEvent(new Event('sstar:cancel-gesture'));setPlacing(null);setTool('select');setWorkshop('array');setLayout(v=>({...v,rightOpen:true}));}
