  function remove(ids=selection){if(selectedEntries.length&&ids.some(id=>selection.includes(id))){deleteArea(ids,selectedEntries);return;}if(ids.some(id=>{const e=level?.entities.find(e=>e.id===id);return e&&objectLocked(e,display);})){setError('操作包含锁定对象，请先解锁');return;}const valid=ids.filter(id=>level?.entities.some(e=>e.id===id&&e.cloneable&&canModify(e,display,layer)));if(!valid.length)return;append(valid.map(id=>({kind:'delete',id})));setSelection([]);setStatus(`已删除 ${valid.length} 个物件，可 Ctrl+Z 撤销`);}
  function deleteArea(ids:number[],entries:string[]){entries=entries.filter(id=>!keyLocked(entryKey(id),display)&&keyVisible(entryKey(id),display));const valid=ids.filter(id=>level?.entities.some(e=>e.id===id&&e.cloneable&&canModify(e,display,layer)));if(!valid.length&&!entries.length)return;edit(w=>{if(view==='world'){w.map.objects??=[];w.map.objects.push(...valid.map(id=>({kind:'delete' as const,id})));w.map.entries=w.map.entries.filter(e=>!entries.includes(e.id));w.map.editor=removeMembers(w.map.editor,new Set([...valid.map(entityKey),...entries.map(entryKey)]));}else{const p=w.levels.find(l=>l.id===view)?.project;if(p){p.operations.push(...valid.map(id=>({kind:'delete' as const,id})));p.editor=removeMembers(p.editor,new Set(valid.map(entityKey)));}}});setSelection([]);setEntryId(null);setSelectedEntries([]);setStatus('已删除 '+(valid.length+entries.length)+' 项，可一步撤销');}
  function duplicate(){if(selectedEntries.length){copyOrganization(organizationSelection());return;}const entities=selected.filter(e=>e.cloneable);if(entities.some(e=>objectLocked(e,display))){setError('选中物件已锁定');return;}if(!entities.length)return;let next=nextId();const used=reservedIds(),copies=entities.map(e=>{while(used.has(next))next++;const newId=next++;used.add(newId);return{id:e.id,newId};});append([{kind:'duplicate',id:copies[0].id,copies,offset:[1,0,0],associations:placementPrefs.associations==='shared'?'shared':'independent'}]);setSelection(copies.map(p=>p.newId));}
  function cloneLinked(){const source=selected.length===1&&selected[0].type==='Guy'?selected[0]:undefined;if(!source)return;const newId=nextId();append([{kind:'duplicate',id:source.id,copies:[{id:source.id,newId}],offset:[1,0,0],associations:'shared'},{kind:'control',id:newId,ids:[newId],targetId:source.id}]);setSelection([newId]);setStatus('已复制为原生同步角色，可一步撤销');}
  function cancel(){window.dispatchEvent(new Event('sstar:cancel-gesture'));if(workshop==='array')setWorkshop('');setArrayPreview([]);setOverlapMode(false);sampleEpoch.current++;setSampling(false);setPlacing(null);setPicking(null);setTool('select');setDraft([]);setStatus('左键选择或移动 · 右键拖动旋转');}
  function choose(p:ObjectPreset,drag=false){window.dispatchEvent(new Event('sstar:cancel-gesture'));sampleEpoch.current++;setSampling(false);setCameraEdit(false);const profile=p.type==='Wall_Set'?'terrain':['Inanimate','Decal'].includes(p.type)?'decoration':'mechanism';setPlacementPrefs({...preference('placementProfile:'+profile,placementProfile(profile)),continuous:true});if(p.type==='Level_Entry'){if(view!=='world'){setError('小关卡入口请在大地图中放置');return;}setEntryPrototype(p);setDialog('entry');setPlacing(null);return;}if(p.type==='Wall_Set'){terrainPreset.current=p.key;setSelection([]);setPlacing(null);setTool('wall');setStatus('体素地形 · 可使用笔刷或矩形铺设');return;}setPlacing({key:p.key,drag,yaw:0});setTool('select');setPicking(null);setStatus(`放置 ${p.label} · R 旋转 · 右键取消`);}
  function place(position:Vec3,yaw:number,key?:string){if(placing?.bundle){append([{kind:'stamp',id:nextId(),bundle:clone(placing.bundle),position,yaw}]);setSelection([]);setPlacing(p=>placementPrefs.continuous&&p?{...p,drag:false}:null);setStatus('已放置独立区域副本，可一步撤销');return;}const p=objects?.presets.find(p=>p.key===(key??placing?.key));if(!p||!position.every(Number.isFinite))return;if(view==='world'&&world&&(position[0]<0||position[1]<0||position[0]>=world.map.width||position[1]>=world.map.height)){setError('位置超出地图');return;}const id=nextId(),ops:EditOp[]=[{kind:'prefab',id,template:p.template,sourceId:p.sourceId,position,assembly:p.placement==='assembly'}];if(yaw&&!['Wall_Set','Ocean_Map'].includes(p.type)){const a=yaw*Math.PI/360,s=Math.sin(a),c=Math.cos(a),x=Number(p.values['orientation.x']??0),y=Number(p.values['orientation.y']??0),z=Number(p.values['orientation.z']??0),w=Number(p.values['orientation.w']??1);ops.push({kind:'transform',id,rotation:[c*x-s*y,s*x+c*y,c*z+s*w,c*w-s*z]});}append(ops);setSelection([id]);recordRecentPlacement(p.key);setStatus('已放置 '+p.label);setPlacing(p=>placementPrefs.continuous&&p?{...p,drag:false}:null);}
  function cell(x:number,y:number,first:boolean,atZ=layer){if(display.categories.terrain.locked){setError('地形已锁定');return;}if(!current.current)return;const w=current.current;if(view==='world'&&tool==='entry'){const levelId=w.levels.find(l=>l.id===quick)?.id??w.levels[0]?.id;if(!levelId){setError('请先新建关卡');return;}if(w.map.entries.some(e=>e.x===x&&e.y===y)){setError('此处已有入口');return;}const e={id:uid('entry'),title:w.levels.find(l=>l.id===levelId)!.title,levelId,x,y,...(entryPrototype?{prototype:{template:entryPrototype.template,sourceId:entryPrototype.sourceId}}:{})};edit(w=>w.map.entries.push(e));if(entryPrototype)recordRecentPlacement(entryPrototype.key);setEntryId(e.id);setTool('select');return;}if(view==='world'&&tool==='spawn'){edit(w=>{w.map.spawn=[x,y];});setTool('select');return;}if(!['floor','wall','erase'].includes(tool))return;
    if(!stroke.current)stroke.current={before:w,cells:new Map()};const radius=(brush-1)/2;
    if(view==='world'){const draft=stroke.current.worldDraft??=clone(w);for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){const px=x+dx,py=y+dy;if(px>=0&&py>=0&&px<draft.map.width&&py<draft.map.height){draft.map.tiles[py*draft.map.width+px]=tool==='floor'?1:tool==='wall'?2:0;for(let z=-1;z<=0;z++)stroke.current.cells.set(`${px},${py},${z}`,{x:px,y:py,z,solid:tool!=='erase'&&(tool==='wall'||z===-1)});}}setStrokeCells([...stroke.current.cells.values()]);}
    else{for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){const px=x+dx,py=y+dy,z=tool==='floor'?Math.round(atZ)-1:tool==='erase'?Math.round(atZ)-1:Math.round(atZ);stroke.current.cells.set(`${px},${py},${z}`,{x:px,y:py,z,solid:tool!=='erase'});}setStrokeCells([...stroke.current.cells.values()]);}
  }
  function stamp(positions:Vec3[]){const p=objects?.presets.find(p=>p.key===placing?.key);if(!p||!['Inanimate','Decal'].includes(p.type))return;let id=nextId();const ops:EditOp[]=positions.flatMap(position=>{const currentId=id++;return[{kind:'prefab' as const,id:currentId,template:p.template,sourceId:p.sourceId,position},{kind:'transform' as const,id:currentId,rotation:nativeQuaternion(placing?.yaw??0,['x','y','z','w'].map(a=>Number(p.values['orientation.'+a]??(a==='w'?1:0))))}];});append(ops);setSelection(ops.filter(o=>o.kind==='prefab').map(o=>o.id));recordRecentPlacement(p.key);setStatus('已铺设 '+positions.length+' 个物件，可一步撤销');if(!placementPrefs.continuous)setPlacing(null);}
  function paintRectangle(positions:Vec3[],voxel=false){if(!positions.length)return;if(display.categories.terrain.locked){setError('地形已锁定');return;}if(!['floor','wall','erase'].includes(tool)||!current.current)return;if(view==='world'){edit(w=>{for(const[x,y]of positions)if(x>=0&&y>=0&&x<w.map.width&&y<w.map.height)w.map.tiles[y*w.map.width+x]=tool==='floor'?1:tool==='wall'?2:0;});}else append([{kind:'terrain',id:nextId(),cells:positions.map(([x,y,z])=>({x,y,z:Math.round(z)-(voxel||tool==='wall'?0:1),solid:tool!=='erase'}))}]);if(terrainPreset.current&&tool!=='erase')recordRecentPlacement(terrainPreset.current);if(!placementPrefs.continuous)setTool('select');}
  function endStroke(cancelled=false){const s=stroke.current;stroke.current=null;if(!s)return;setStrokeCells([]);if(cancelled)return;if(view==='world'){if(s.worldDraft)update(s.worldDraft,true,s.before);}else if(s.cells.size){append([{kind:'terrain',id:nextId(),cells:[...s.cells.values()]}]);if(terrainPreset.current&&tool!=='erase')recordRecentPlacement(terrainPreset.current);}if(!placementPrefs.continuous)setTool('select');}
  const committedLevel=useMemo(()=>optimisticTransforms(level,pendingTransforms),[level,pendingTransforms]);
  const visualLevel=useMemo(()=>{const level=committedLevel;if(!level||!strokeCells.length)return level;const cells=new Map((level.terrain??[]).map(p=>[`${p.x},${p.y},${p.z-1}`,p]));for(const p of strokeCells){const key=`${p.x},${p.y},${p.z}`;if(p.solid)cells.set(key,{x:p.x,y:p.y,z:p.z+1});else cells.delete(key);}return{...level,terrain:[...cells.values()]};},[committedLevel,strokeCells]);
  async function addBlank(){await task(async()=>{const p=await api.levelCreateBlank();addLevel(p,'新关卡 '+String((world?.levels.length??0)+1).padStart(2,'0'));});}
