  function copyLevel(id=view){const l=current.current?.levels.find(l=>l.id===id);if(!l)return;const newId=uid('level');let title=l.title+' 副本',n=2;while(current.current?.levels.some(l=>l.title===title))title=l.title+' 副本 '+n++;edit(w=>{const index=w.levels.findIndex(l=>l.id===id);w.levels.splice(index+1,0,{id:newId,title,project:{...clone(l.project),name:newId}});});setView(newId);setContext(null);}
