  function resizePanel(side:'left'|'right'|'bottom',e:React.PointerEvent){const startX=e.clientX,startY=e.clientY,initial=layout[side],target=e.currentTarget as HTMLElement;target.setPointerCapture(e.pointerId);const move=(event:PointerEvent)=>{const delta=side==='left'?event.clientX-startX:side==='right'?startX-event.clientX:startY-event.clientY;setLayout(v=>({...v,[side]:Math.round(Math.max(side==='bottom'?130:180,Math.min(side==='bottom'?420:460,initial+delta)))}));};const end=()=>{target.removeEventListener('pointermove',move);target.removeEventListener('pointerup',end);target.removeEventListener('pointercancel',end);};target.addEventListener('pointermove',move);target.addEventListener('pointerup',end);target.addEventListener('pointercancel',end);}
  async function loadExample(which:string){await task(async()=>{if(dirty&&!confirm('放弃当前未保存的修改？'))return;accept(which==='recreations'?await api.worldRecreations():which==='studio'?await api.worldStudioExample():await api.worldExample());setDialog('');});}
  async function capture(bounds?:{min:Vec3;max:Vec3}){if(!selectedLevel){setError('请进入小关后复制区域');return;}await task(async()=>{await parameterQueue.current;const p=current.current!.levels.find(l=>l.id===currentView.current)!.project;const bundle=await api.regionCapture(p,{ids:selection.filter(id=>{const e=level?.entities.find(e=>e.id===id);return e&&canModify(e,display,layer);}),bounds,includeBackground:display.categories.background.visible&&!display.categories.background.locked});setClipboard(bundle);setTool('select');setWorkshop('region');setLayout(v=>({...v,rightOpen:true}));setStatus('区域已复制，Ctrl+V 预览粘贴');});}
  function pasteBundle(bundle=clipboard,drag=false){if(!bundle)return;if(view==='world'){setError('区域组合用于小关；大地图入口请使用入口工具');return;}cancel();setPlacing({key:uid('region'),bundle:clone(bundle),yaw:0,drag});setStatus('放置区域 · R 旋转 · 右键或 Esc 取消');}
  async function saveAssembly(){if(!clipboard)return;await task(async()=>{await api.assemblySave(clipboard);setAssemblies(await api.assemblyList());setWorkshop('library');setStatus('已保存组合模板，放下的副本独立编辑');});}
  async function launch(request?:RunRequest){if(!current.current)return;const r=request??{mode:runMode,levelIds:runMode==='single'?[view]:runMode==='subset'?runIds:[]};if(r.mode==='single'&&view==='world'){setError('请先选择一个小关卡');return;}await task(async()=>{await parameterQueue.current;await previewSession.current.flush();const snapshot=clone(current.current!);await api.recoveryWrite(snapshot);const checked=await api.runValidate(snapshot,r);setIssues(checked);if(checked.some(i=>i.severity==='error')){setIssueOpen(true);throw Error('所选测试范围存在错误，请先修复；其他关卡不参与本次检查。');}setDialog('');const estimate=await api.preparationEstimate();if(!estimate.canPrepare)throw Error(`工作区空间不足，需约 ${(estimate.requiredBytes/2**30).toFixed(1)} GB，可用 ${(estimate.availableBytes/2**30).toFixed(1)} GB。请在工程菜单更换工作区并重启。`);setStatus(estimate.prepared?'正在准备试玩…':`首次试玩正在复制约 ${(estimate.sourceBytes/2**30).toFixed(1)} GB 游戏文件到工作区…`);setStatus(await api.runLaunch(snapshot,r));},'校验所选范围并准备专用测试战役…');}

  function startSample(){const id=selection.find(id=>{const e=level?.entities.find(e=>e.id===id);return e&&canModify(e,display,layer);});cancel();setCameraEdit(false);if(id!==undefined)void sampleObject(id);else{setSampling(true);setStatus('吸管：点击物件取样，Esc 取消');}}
  async function sampleObject(id:number){const entity=level?.entities.find(e=>e.id===id);if(!entity||!canModify(entity,display,layer))return;if(protectedCameraIds.has(id)){setStatus('请在原生区域面板复制相机对象');return;}if(entity.type==='Wall_Set'){const cell=level?.terrain?.find(c=>c.id===id);if(cell)sampleTerrain([cell.x,cell.y,cell.z-1],[0,0,1]);return;}if(!selectedLevel){setError('请进入小关卡后取样物件');return;}const capturedView=view,epoch=++sampleEpoch.current,source=selectedLevel.project,strategy=placementPrefs.associations,profile=['Inanimate','Decal'].includes(entity.type)?'decoration':'mechanism';window.dispatchEvent(new Event('sstar:cancel-gesture'));setPlacing(null);setSampling(false);setTool('select');setCameraEdit(false);setStatus('正在取样物件…');try{if(strategy==='material'){const fields=PROFILE_FIELDS[entity.type]??[],values=new Map(entity.nativeProperties?.map(p=>[p.field.name,p.value]));const candidates=objects?.presets.filter(p=>p.parsed&&p.type===entity.type&&p.mesh===entity.mesh)??[];const score=(p:ObjectPreset)=>fields.reduce((sum,key)=>sum+(JSON.stringify(p.signature[key]??p.values[key])===JSON.stringify(values.get(key))?1:0),0);const preset=candidates.sort((a,b)=>score(b)-score(a))[0];if(!preset)throw Error('找不到该物件对应的原生素材');if(currentView.current!==capturedView||sampleEpoch.current!==epoch)return;choose(preset);setPlacing({key:preset.key,yaw:entity.yaw});}else{let cache=sampleCache.current.get(entity);if(!cache)sampleCache.current.set(entity,cache=new Map());let bundle=cache.get(strategy);if(!bundle){bundle=await api.regionCapture(source,{ids:[id],single:true,includeBackground:!display.categories.background.locked,associations:strategy});cache.set(strategy,bundle);}if(currentView.current!==capturedView||sampleEpoch.current!==epoch)return;setPlacementPrefs({...preference('placementProfile:'+profile,placementProfile(profile)),continuous:true,associations:strategy});setPlacing({key:uid('sample'),bundle,yaw:0});setStatus(bundle.warnings.length?'已取样 · '+bundle.warnings.join('；'):'已取样，连续放置 · 中键可直接取样其他物件或地形');}}catch(e){if(sampleEpoch.current===epoch)setError(String(e));}}

